function [audit, selection] = lockRawMotionTop30(audit, sequenceOrder, targetCount)
audit.top30_raw_motion_selected = false(height(audit),1);
audit.raw_motion_quality_score_nm = nan(height(audit),1);
audit.raw_motion_quality_rank = nan(height(audit),1);
for i = 1:numel(sequenceOrder)
    sequenceMask = audit.sequence==sequenceOrder(i);
    eligible = sequenceMask & audit.raw_eligible_25pct & audit.v42_evaluable;
    assert(sum(eligible)>=targetCount, ...
        'Sequence %s has fewer than %d usable Raw/V42 pairs.',sequenceOrder(i),targetCount);
    xErrorUm = audit.raw_local_dx_um(eligible)-audit.expected_signed_step_um(eligible);
    yErrorUm = audit.raw_local_dy_um(eligible);
    scoreNm = 1000*hypot(xErrorUm,yErrorUm);
    eligibleRows = find(eligible);
    rankTable = table(eligibleRows,scoreNm,audit.end_frame_index(eligible), ...
        'VariableNames',{'row_index','raw_motion_quality_score_nm','end_frame_index'});
    rankTable = sortrows(rankTable,{'raw_motion_quality_score_nm','end_frame_index'});
    audit.raw_motion_quality_score_nm(rankTable.row_index)=rankTable.raw_motion_quality_score_nm;
    audit.raw_motion_quality_rank(rankTable.row_index)=(1:height(rankTable))';
    audit.top30_raw_motion_selected(rankTable.row_index(1:targetCount))=true;
end
selection = audit(:,{'sequence','end_frame_index','raw_eligible_25pct','v42_evaluable', ...
    'raw_local_dx_um','raw_local_dy_um','expected_signed_step_um', ...
    'raw_motion_quality_score_nm','raw_motion_quality_rank','top30_raw_motion_selected'});
selection = selection(selection.raw_eligible_25pct & selection.v42_evaluable,:);
selection = sortrows(selection,{'sequence','raw_motion_quality_rank'});
end

function summary = buildDetailedDisplacementSummary(audit, sequenceOrder, conditionLabels)
n = numel(sequenceOrder);
rows = cell(n, 33);
for i = 1:n
    seq = sequenceOrder(i);
    allRows = audit(audit.sequence == seq, :);
    g = allRows(allRows.top30_raw_motion_selected, :);
    nominal = abs(g.expected_signed_step_um(1));
    raw = g.raw_boundary_dx_um;
    v42 = g.v42_boundary_dx_um;
    rawErr = abs(raw - g.expected_signed_step_um) * 1000;
    v42Err = abs(v42 - g.expected_signed_step_um) * 1000;
    rawWithin = g.raw_within_grid_nm;
    v42Within = g.v42_within_grid_nm;
    rows(i,:) = {seq, conditionLabels(i), string(g.magnification(1)), nominal, height(allRows), ...
        sum(~allRows.cross_session), height(g), 100*height(g)/sum(~allRows.cross_session), ...
        abs(mean(raw)), abs(mean(v42)), (abs(mean(raw))-nominal)*1000, (abs(mean(v42))-nominal)*1000, ...
        std(raw,0)*1000, std(v42,0)*1000, 100*(1-std(v42,0)/std(raw,0)), ...
        mean(rawErr), mean(v42Err), 100*(1-mean(v42Err)/mean(rawErr)), ...
        median(rawErr), median(v42Err), prctile(rawErr,90), prctile(v42Err,90), ...
        mean(rawWithin), mean(v42Within), 100*(1-mean(v42Within)/mean(rawWithin)), ...
        median(rawWithin), median(v42Within), prctile(rawWithin,90), prctile(v42Within,90), ...
        sum(v42Err < rawErr), 100*sum(v42Err < rawErr)/height(g), ...
        sum(v42Within < rawWithin), 100*sum(v42Within < rawWithin)/height(g)};
end
names = {'sequence','condition','magnification','nominal_step_um','total_adjacent_pairs', ...
    'within_session_pairs','paired_count','coverage_within_session_pct', ...
    'raw_mean_magnitude_um','v42_mean_magnitude_um','raw_mean_command_bias_nm','v42_mean_command_bias_nm', ...
    'raw_step_sd_nm','v42_step_sd_nm','step_sd_reduction_pct', ...
    'raw_command_mae_nm','v42_command_mae_nm','command_mae_reduction_pct', ...
    'raw_command_median_ae_nm','v42_command_median_ae_nm','raw_command_p90_ae_nm','v42_command_p90_ae_nm', ...
    'raw_within_mean_nm','v42_within_mean_nm','within_reduction_pct', ...
    'raw_within_median_nm','v42_within_median_nm','raw_within_p90_nm','v42_within_p90_nm', ...
    'v42_closer_to_command_count','v42_closer_to_command_pct', ...
    'v42_lower_within_count','v42_lower_within_pct'};
summary = cell2table(rows, 'VariableNames', names);
end

function pooled = buildPooledSummary(audit)
groups = ["All paired steps", "50x", "20x"];
rows = cell(3, 11);
primary = audit.top30_raw_motion_selected;
for i = 1:3
    if i == 1
        g = audit(primary,:);
    else
        g = audit(primary & audit.magnification == groups(i),:);
    end
    rawErr = abs(g.raw_boundary_dx_um-g.expected_signed_step_um)*1000;
    v42Err = abs(g.v42_boundary_dx_um-g.expected_signed_step_um)*1000;
    rawWithin = g.raw_within_grid_nm;
    v42Within = g.v42_within_grid_nm;
    rows(i,:) = {groups(i), height(g), mean(rawErr), mean(v42Err), 100*(1-mean(v42Err)/mean(rawErr)), ...
        mean(rawWithin), mean(v42Within), 100*(1-mean(v42Within)/mean(rawWithin)), ...
        sum(v42Err<rawErr), sum(v42Within<rawWithin), 100*sum(v42Within<rawWithin)/height(g)};
end
pooled = cell2table(rows, 'VariableNames', {'population','paired_count','raw_command_mae_nm', ...
    'v42_command_mae_nm','command_mae_reduction_pct','raw_within_mean_nm','v42_within_mean_nm', ...
    'within_reduction_pct','v42_closer_to_command_count','v42_lower_within_count','v42_lower_within_pct'});
end

function clean = buildToleranceSummary(tolerance, sequenceOrder, conditionLabels)
tolerance.sequence = string(tolerance.sequence);
rows = cell(0,8);
for i = 1:numel(sequenceOrder)
    g = tolerance(tolerance.sequence == sequenceOrder(i),:);
    g = sortrows(g,'tolerance_fraction');
    for j = 1:height(g)
        rows(end+1,:) = {sequenceOrder(i), conditionLabels(i), 100*g.tolerance_fraction(j), ...
            g.raw_eligible_count(j), g.paired_count(j), g.step_sd_reduction_pct(j), ...
            g.within_grid_reduction_pct(j), string(g.step_sd_direction(j))}; %#ok<AGROW>
    end
end
clean = cell2table(rows, 'VariableNames', {'sequence','condition','tolerance_pct','raw_eligible_count', ...
    'paired_count','step_sd_reduction_pct','within_reduction_pct','step_sd_direction'});
end

function derived = buildCdSummary(cdTable, cdSummary)
raw = cdSummary(string(cdSummary.case)=="raw",:);
v42 = cdSummary(string(cdSummary.case)=="v42_e120",:);
semMean = mean(cdTable.sem_diameter_um);
rows = {
    'Mean diameter', semMean*1000, raw.mean_diameter_um*1000, v42.mean_diameter_um*1000, NaN; ...
    'MAE', NaN, raw.mean_abs_error_nm, v42.mean_abs_error_nm, 100*(1-v42.mean_abs_error_nm/raw.mean_abs_error_nm); ...
    'Median AE', NaN, raw.median_abs_error_nm, v42.median_abs_error_nm, 100*(1-v42.median_abs_error_nm/raw.median_abs_error_nm); ...
    'RMSE', NaN, raw.rmse_nm, v42.rmse_nm, 100*(1-v42.rmse_nm/raw.rmse_nm); ...
    'Maximum AE', NaN, raw.max_abs_error_nm, v42.max_abs_error_nm, 100*(1-v42.max_abs_error_nm/raw.max_abs_error_nm)};
derived = cell2table(rows, 'VariableNames', {'metric','sem_reference_nm','raw_nm','v42_nm','reduction_pct'});
end

function drawFullFovLocator(image, centers, cropRect, pitchPx, pillarQuadrant, innerCorner, umPerPx, scaleBarUm, titleText, outputPath)
% The layout identity is fixed by the four-region sample map.  The selected
% pillar block is the sample-center-facing 3x3 corner.  Each acquisition
% carries its own orientation; 50x is identity and 20x is vertically flipped.
if contains(string(innerCorner),'left')
    centerX = min(centers(:,1)) - 0.75*pitchPx;
else
    centerX = max(centers(:,1)) + 0.75*pitchPx;
end
if contains(string(innerCorner),'upper')
    centerY = min(centers(:,2)) - 0.75*pitchPx;
else
    centerY = max(centers(:,2)) + 0.75*pitchPx;
end
sampleCenter = [centerX,centerY];
heightPx = size(image,1);
widthPx = size(image,2);
sampleCenter(1) = min(max(sampleCenter(1),1),widthPx);
sampleCenter(2) = min(max(sampleCenter(2),1),heightPx);

fig = figure('Units','inches','Position',[1,1,6.55,4.95]);
ax = axes(fig);
imagesc(ax,image,[0,255]);
colormap(ax,gray(256));
axis(ax,'image'); axis(ax,'off');
title(ax,titleText,'FontSize',11,'FontWeight','normal','Interpreter','tex');
hold(ax,'on');

pillarColor = [0.86,0.22,0.16];
viaColor = [0.00,0.56,0.72];
selectionColor = [1.00,0.78,0.05];
pillarRect = quadrantRectangle(pillarQuadrant,sampleCenter,widthPx,heightPx);
viaQuadrant = oppositeQuadrant(pillarQuadrant);
viaRect = quadrantRectangle(viaQuadrant,sampleCenter,widthPx,heightPx);
rectangle(ax,'Position',pillarRect, ...
    'EdgeColor',pillarColor,'LineWidth',1.35,'LineStyle','--');
rectangle(ax,'Position',viaRect, ...
    'EdgeColor',viaColor,'LineWidth',1.35,'LineStyle','--');
rectangle(ax,'Position',[cropRect(1),cropRect(2),cropRect(3)-cropRect(1),cropRect(4)-cropRect(2)], ...
    'EdgeColor',[0,0,0],'LineWidth',4.2);
rectangle(ax,'Position',[cropRect(1),cropRect(2),cropRect(3)-cropRect(1),cropRect(4)-cropRect(2)], ...
    'EdgeColor',selectionColor,'LineWidth',2.4);
plot(ax,centers(:,1),centers(:,2),'o','MarkerSize',4.0,'LineWidth',0.8, ...
    'MarkerEdgeColor',[0,0,0],'MarkerFaceColor',selectionColor);
plot(ax,sampleCenter(1),sampleCenter(2),'p','MarkerSize',9,'LineWidth',1.0, ...
    'MarkerEdgeColor',[0,0,0],'MarkerFaceColor',[1,1,1]);

pillarLabel = [pillarRect(1)+0.55*pillarRect(3),pillarRect(2)+0.22*pillarRect(4)];
viaLabel = [viaRect(1)+0.46*viaRect(3),viaRect(2)+0.48*viaRect(4)];
if lower(string(pillarQuadrant))=="lower_right" && pillarRect(3)<0.12*widthPx
    text(ax,pillarLabel(1),pillarRect(2)+0.55*pillarRect(4),'PILLAR REGION','Color',pillarColor, ...
        'BackgroundColor','w','Margin',1.5,'FontWeight','bold','FontSize',7.5, ...
        'HorizontalAlignment','center','Rotation',90);
else
    text(ax,pillarLabel(1),pillarLabel(2),'PILLAR REGION','Color',pillarColor, ...
        'BackgroundColor','w','Margin',2,'FontWeight','bold','FontSize',9, ...
        'HorizontalAlignment','center');
end
text(ax,viaLabel(1),viaLabel(2),'VIA REGION','Color',viaColor, ...
    'BackgroundColor','w','Margin',2,'FontWeight','bold','FontSize',9, ...
    'HorizontalAlignment','center');
selectionLabelX = mean(cropRect([1,3]));
if selectionLabelX > widthPx-220
    selectionLabelX = widthPx-250;
end
selectionLabelY = max(18,cropRect(2)-18);
text(ax,selectionLabelX,selectionLabelY,'CENTER-FACING 3\times3', ...
    'Color',[0.08,0.08,0.08],'BackgroundColor',selectionColor,'Margin',2, ...
    'FontWeight','bold','FontSize',8.2,'HorizontalAlignment','center','Interpreter','tex');
plot(ax,[selectionLabelX+95,mean(cropRect([1,3]))],[selectionLabelY+5,cropRect(2)], ...
    '-','Color',[0.15,0.15,0.15],'LineWidth',1.0);
if sampleCenter(1)>0.75*widthPx
    text(ax,sampleCenter(1)-12,sampleCenter(2)-12,'SAMPLE-CENTER JUNCTION', ...
        'Color',[0.08,0.08,0.08],'BackgroundColor','w','Margin',2, ...
        'FontSize',7.5,'HorizontalAlignment','right','VerticalAlignment','bottom');
else
    text(ax,sampleCenter(1)+12,sampleCenter(2)+15,'SAMPLE-CENTER JUNCTION', ...
        'Color',[0.08,0.08,0.08],'BackgroundColor','w','Margin',2, ...
        'FontSize',7.8,'HorizontalAlignment','left','VerticalAlignment','top');
