function rect = quadrantRectangle(quadrant,center,widthPx,heightPx)
switch lower(string(quadrant))
    case "upper_left"
        rect = [1,1,center(1)-1,center(2)-1];
    case "upper_right"
        rect = [center(1),1,widthPx-center(1),center(2)-1];
    case "lower_left"
        rect = [1,center(2),center(1)-1,heightPx-center(2)];
    case "lower_right"
        rect = [center(1),center(2),widthPx-center(1),heightPx-center(2)];
    otherwise
        error('Unknown quadrant: %s',quadrant);
end
end

function opposite = oppositeQuadrant(quadrant)
switch lower(string(quadrant))
    case "upper_left"
        opposite = "lower_right";
    case "upper_right"
        opposite = "lower_left";
    case "lower_left"
        opposite = "upper_right";
    case "lower_right"
        opposite = "upper_left";
    otherwise
        error('Unknown quadrant: %s',quadrant);
end
end

function result = measurePillarContrast(image, centers, ids, radiusPx, magnification, caseName)
rows = cell(size(centers,1),8);
outer = ceil(1.70*radiusPx);
for i = 1:size(centers,1)
    xc = round(centers(i,1)); yc = round(centers(i,2));
    x0 = max(1,xc-outer); x1 = min(size(image,2),xc+outer);
    y0 = max(1,yc-outer); y1 = min(size(image,1),yc+outer);
    [xx,yy] = meshgrid(x0:x1,y0:y1);
    distance = hypot(xx-centers(i,1),yy-centers(i,2));
    patch = double(image(y0:y1,x0:x1));
    featureLevel = median(patch(distance <= 0.55*radiusPx),'omitnan');
    backgroundLevel = median(patch(distance >= 1.25*radiusPx & distance <= 1.70*radiusPx),'omitnan');
    signedDifference = featureLevel-backgroundLevel;
    signedMichelson = 100*signedDifference/(featureLevel+backgroundLevel);
    if signedDifference < 0
        polarity = "dark-on-bright";
    else
        polarity = "bright-on-dark";
    end
    rows(i,:) = {string(magnification),ids(i),string(caseName),featureLevel,backgroundLevel, ...
        signedDifference,signedMichelson,polarity};
end
result = cell2table(rows,'VariableNames',{'magnification','pillar_id','case', ...
    'pillar_core_median_8bit','local_background_median_8bit','signed_difference_8bit', ...
    'signed_michelson_pct','polarity'});
end

function summary = summarizePillarContrast(contrastTable)
magnification = ["50x";"50x";"20x";"20x"];
caseName = ["Raw";"V42 epoch 120";"Raw";"V42 epoch 120"];
rows = cell(4,10);
for i = 1:4
    g = contrastTable(string(contrastTable.magnification)==magnification(i) & ...
        string(contrastTable.case)==caseName(i),:);
    delta = g.signed_difference_8bit;
    michelson = g.signed_michelson_pct;
    if median(delta) < 0
        polarity = "dark-on-bright";
    else
        polarity = "bright-on-dark";
    end
    rows(i,:) = {magnification(i),caseName(i),height(g), ...
        median(g.pillar_core_median_8bit),median(g.local_background_median_8bit), ...
        median(delta),mean(delta),std(delta),median(michelson),polarity};
end
summary = cell2table(rows,'VariableNames',{'magnification','case','pillar_count', ...
    'median_pillar_core_8bit','median_local_background_8bit','median_signed_difference_8bit', ...
    'mean_signed_difference_8bit','std_signed_difference_8bit','median_signed_michelson_pct','polarity'});
end

