function [edgeTable, profile] = analyzeNinePillarEdges(rawImage, v42Image, centers, ids, radiusPx, umPerPx, polarity, magnification)
rows = cell(0,6);
centralIndex = 5;
profile = struct();
for i = 1:size(centers,1)
    [xRaw, sRaw, wRaw] = normalizedPillarProfile(rawImage, centers(i,:), radiusPx, umPerPx, polarity);
    [xV42, sV42, wV42] = normalizedPillarProfile(v42Image, centers(i,:), radiusPx, umPerPx, polarity);
    rows(end+1,:) = {string(magnification), ids(i), 'Raw', mean(wRaw,'omitnan')*umPerPx*1000, wRaw(1)*umPerPx*1000, wRaw(2)*umPerPx*1000}; %#ok<AGROW>
    rows(end+1,:) = {string(magnification), ids(i), 'V42 epoch 120', mean(wV42,'omitnan')*umPerPx*1000, wV42(1)*umPerPx*1000, wV42(2)*umPerPx*1000}; %#ok<AGROW>
    if i == centralIndex
        profile.x_um = xRaw;
        profile.raw = sRaw;
        profile.v42 = interp1(xV42, sV42, xRaw, 'linear', 'extrap');
    end
end
edgeTable = cell2table(rows,'VariableNames',{'magnification','pillar_id','case','transition_width_nm','left_width_nm','right_width_nm'});
end

function [xUm, score, widthsPx] = normalizedPillarProfile(image, center, radiusPx, umPerPx, polarity)
xc = center(1); yc = center(2);
halfSpan = max(8, round(radiusPx*1.65));
yBand = max(1, round(radiusPx*0.18));
x0 = max(1, round(xc)-halfSpan); x1 = min(size(image,2), round(xc)+halfSpan);
y0 = max(1, round(yc)-yBand); y1 = min(size(image,1), round(yc)+yBand);
profile = mean(double(image(y0:y1,x0:x1)),1);
xPx = (x0:x1)-xc;
centerMask = abs(xPx) <= 0.30*radiusPx;
backgroundMask = abs(xPx) >= 1.30*radiusPx & abs(xPx) <= 1.60*radiusPx;
featureLevel = median(profile(centerMask));
backgroundLevel = median(profile(backgroundMask));
if strcmpi(polarity,'dark')
    score = (backgroundLevel-profile)/(backgroundLevel-featureLevel);
else
    score = (profile-backgroundLevel)/(featureLevel-backgroundLevel);
end
xUm = xPx*umPerPx;
leftMask = xPx >= -1.60*radiusPx & xPx <= 0;
rightMask = xPx >= 0 & xPx <= 1.60*radiusPx;
leftWidth = monotonicTransitionWidth(xPx(leftMask), score(leftMask));
rightWidth = monotonicTransitionWidth(-fliplr(xPx(rightMask)), fliplr(score(rightMask)));
widthsPx = [leftWidth,rightWidth];
end

function width = monotonicTransitionWidth(x, y)
x = double(x(:)); y = double(y(:));
if numel(x) < 4
    width = NaN; return;
end
y = cummax(y);
[yu, ia] = unique(y,'stable');
xu = x(ia);
if min(yu) > 0.1 || max(yu) < 0.9 || numel(yu) < 2
    width = NaN; return;
end
x10 = interp1(yu,xu,0.1,'linear');
x90 = interp1(yu,xu,0.9,'linear');
width = abs(x90-x10);
end

