title(ax,'Stepwise improvement in center-nine consistency','FontSize',11,'FontWeight','normal');
subtitle(ax,'Strict paired-step comparison; no tie credit','FontSize',8.5);
ylim(ax,[0,105]);
text(ax,1:height(summary),values+2.2,compose('%.1f%%',values),'HorizontalAlignment','center','FontSize',8.5,'FontWeight','bold');
styleAxes(ax,gridColor);
exportFigure(fig,outputPath);
end

function drawToleranceSensitivity(cleanTolerance, metricField, titleText, yLabelText, sequenceOrder, conditionLabels, gridColor, outputPath)
palette=[0.10,0.42,0.67;0.25,0.25,0.25;0.78,0.57,0.10;0.55,0.35,0.62];
markers={'o','s','^','d'};
fig=figure('Units','inches','Position',[1,1,6.35,3.6]);
ax=axes(fig); hold(ax,'on');
for i=1:numel(sequenceOrder)
    g=cleanTolerance(string(cleanTolerance.sequence)==sequenceOrder(i),:);
    plot(ax,g.tolerance_pct,g.(metricField),'-','Color',palette(i,:),'Marker',markers{i}, ...
        'MarkerFaceColor',palette(i,:),'MarkerSize',4.5,'DisplayName',conditionLabels(i));
end
yline(ax,0,'--','Color',[0.3,0.3,0.3],'HandleVisibility','off');
set(ax,'XTick',[20,25,30]); xlim(ax,[18.5,31.5]);
xlabel(ax,'Raw-screening tolerance (%)'); ylabel(ax,yLabelText);
title(ax,titleText,'FontSize',11,'FontWeight','normal');
subtitle(ax,'Positive values indicate lower V42 variability','FontSize',8.5);
legend(ax,'Location','best','Box','off','Interpreter','none');
styleAxes(ax,gridColor);
exportFigure(fig,outputPath);
end

function drawUsableVsTop30(audit, rawColor, v42Color, gridColor, outputPath)
g=audit(audit.sequence=="20x_0p5um",:);
usable=g.raw_eligible_25pct & g.v42_evaluable;
selected=g.top30_raw_motion_selected;
values=[std(g.raw_boundary_dx_um(usable),0)*1000,std(g.v42_boundary_dx_um(usable),0)*1000; ...
        std(g.raw_boundary_dx_um(selected),0)*1000,std(g.v42_boundary_dx_um(selected),0)*1000];
fig=figure('Units','inches','Position',[1,1,6.25,3.7]);
ax=axes(fig); b=bar(ax,values,'grouped','LineWidth',0.8);
b(1).FaceColor=rawColor; b(2).FaceColor=v42Color; b(1).EdgeColor='none'; b(2).EdgeColor='none';
set(ax,'XTickLabel',{sprintf('All usable %d',sum(usable)),sprintf('Raw-ranked %d',sum(selected))});
ylabel(ax,'Signed-step standard deviation (nm)');
title(ax,'Effect of the fixed 30-step backup selection','FontSize',11,'FontWeight','normal');
subtitle(ax,'20×, 0.5 µm sequence','FontSize',8.5,'Interpreter','none');
legend(ax,{'Raw','V42 epoch 120'},'Location','northeast','Box','off');
ylim(ax,[0,max(values(:))*1.25]);
for j=1:2
    text(ax,b(j).XEndPoints,b(j).YEndPoints+0.035*max(values(:)),compose('%.2f',b(j).YEndPoints),'HorizontalAlignment','center','FontSize',8);
end
text(ax,1,max(values(1,:))+0.13*max(values(:)),sprintf('V42 %.1f%% lower',100*(1-values(1,2)/values(1,1))), ...
    'HorizontalAlignment','center','Color',v42Color,'FontWeight','bold','FontSize',8.5);
text(ax,2,max(values(2,:))+0.13*max(values(:)),sprintf('V42 %.1f%% lower',100*(1-values(2,2)/values(2,1))), ...
    'HorizontalAlignment','center','Color',v42Color,'FontWeight','bold','FontSize',8.5);
styleAxes(ax,gridColor);
exportFigure(fig,outputPath);
end

function drawRawMotionAudit(audit, direction, accentColor, excludeColor, inkColor, gridColor, outputPath)
g=audit(audit.sequence=="20x_0p5um",:);
x=g.end_frame_index;
excluded=~g.raw_eligible_25pct;
selected=g.top30_raw_motion_selected;
backup=g.raw_eligible_25pct & g.v42_evaluable & ~selected;
fig=figure('Units','inches','Position',[1,1,6.4,3.55]);
ax=axes(fig); hold(ax,'on');
if strcmpi(direction,'x')
    values=abs(g.raw_local_dx_um); nominal=0.5; limit=0.125;
    patch(ax,[min(x),max(x),max(x),min(x)],[nominal-limit,nominal-limit,nominal+limit,nominal+limit], ...
        [0.88,0.92,0.96],'EdgeColor','none','FaceAlpha',0.75,'DisplayName','Accepted reference band');
    yline(ax,nominal,'--','Color',inkColor,'LineWidth',1.1,'DisplayName','PI closed-loop displacement reference');
    ylabel(ax,'Raw x-step magnitude (\mum)','Interpreter','tex');
    title(ax,'Raw x-direction motion audit','FontSize',11,'FontWeight','normal');
    ylim(ax,[0,max(values)*1.12]);
else
    values=abs(g.raw_local_dy_um); limit=0.125;
    patch(ax,[min(x),max(x),max(x),min(x)],[0,0,limit,limit], ...
        [0.88,0.92,0.96],'EdgeColor','none','FaceAlpha',0.75,'DisplayName','Accepted cross-axis band');
    yline(ax,limit,'--','Color',inkColor,'LineWidth',1.1,'DisplayName','25% limit');
    ylabel(ax,'Absolute Raw y-motion (\mum)','Interpreter','tex');
    title(ax,'Raw cross-axis motion audit','FontSize',11,'FontWeight','normal');
    ylim(ax,[0,max(values)*1.12]);
end
plot(ax,x,values,'-','Color',[0.55,0.55,0.55],'LineWidth',0.9,'DisplayName','Raw local motion');
plot(ax,x(selected),values(selected),'o','Color',accentColor,'MarkerFaceColor',accentColor,'MarkerSize',4.2,'DisplayName','Selected top 30');
plot(ax,x(backup),values(backup),'o','Color',[0.35,0.35,0.35],'MarkerFaceColor','w','MarkerSize',4.0,'DisplayName','Usable backup');
plot(ax,x(excluded),values(excluded),'x','Color',excludeColor,'MarkerSize',8,'LineWidth',1.8,'DisplayName','Excluded at 25%');
xlabel(ax,'End-frame index');
subtitle(ax,'20×, 0.5 µm; thirty steps selected by Raw motion only','FontSize',8.5,'Interpreter','none');
legend(ax,'Location','best','Box','off');
styleAxes(ax,gridColor);
exportFigure(fig,outputPath);
end

function summary = buildTrainingSummary(trainingLog)
metrics = ["Reconstruction loss"; "Gradient-magnitude loss"; "Edge-orientation loss"];
startEpoch = repmat(trainingLog.epoch(1),3,1);
endEpoch = repmat(trainingLog.epoch(end),3,1);
startValue = [trainingLog.loss_rec(1); trainingLog.loss_gradmag(1); trainingLog.loss_edgeori(1)];
endValue = [trainingLog.loss_rec(end); trainingLog.loss_gradmag(end); trainingLog.loss_edgeori(end)];
favorableChangePct = 100*(1-endValue./startValue);
direction = repmat("lower",3,1);
summary = table(metrics,startEpoch,startValue,endEpoch,endValue,favorableChangePct,direction, ...
    'VariableNames',{'metric','start_epoch','start_value','end_epoch','end_value','favorable_change_pct','favorable_direction'});
end

function drawTrainingLosses(trainingLog, rawColor, v42Color, accentColor, gridColor, outputPath)
epoch = trainingLog.epoch;
losses = [trainingLog.loss_rec, trainingLog.loss_gradmag, trainingLog.loss_edgeori];
normalized = 100*losses./losses(1,:);
reductions = 100*(1-losses(end,:)./losses(1,:));
fig=figure('Units','inches','Position',[1,1,6.45,3.65]);
ax=axes(fig); hold(ax,'on');
plot(ax,epoch,normalized(:,1),'-','Color',rawColor,'DisplayName',sprintf('Reconstruction (%.1f%% lower)',reductions(1)));
plot(ax,epoch,normalized(:,2),'-','Color',v42Color,'DisplayName',sprintf('Gradient magnitude (%.1f%% lower)',reductions(2)));
plot(ax,epoch,normalized(:,3),'-','Color',accentColor,'DisplayName',sprintf('Edge orientation (%.1f%% lower)',reductions(3)));
yline(ax,100,'--','Color',[0.35,0.35,0.35],'HandleVisibility','off');
xlabel(ax,'Training epoch'); ylabel(ax,'Loss relative to epoch 1 (%)');
title(ax,'MOSR training-loss components','FontSize',11,'FontWeight','normal');
subtitle(ax,'Unsmoothed epoch values; epoch 1 = 100%','FontSize',8.5);
xlim(ax,[1,120]);
finiteValues=normalized(isfinite(normalized));
ylim(ax,[max(0,min(finiteValues)-5),max(finiteValues)+5]);
legend(ax,'Location','best','Box','off');
styleAxes(ax,gridColor);
exportFigure(fig,outputPath);
end

function rect = cropAroundCenters(centers, margin, imageSize)
x0=max(1,floor(min(centers(:,1))-margin)); x1=min(imageSize(2),ceil(max(centers(:,1))+margin));
y0=max(1,floor(min(centers(:,2))-margin)); y1=min(imageSize(1),ceil(max(centers(:,2))+margin));
rect=[x0,y0,x1,y1];
end

function image = readGray(path)
image=imread(path);
if ndims(image)==3
    image=rgb2gray(image);
end
image=uint8(image);
end

function tableData = readCsv(path)
options = detectImportOptions(path, 'Delimiter', ',', 'VariableNamingRule', 'preserve', 'Encoding', 'UTF-8');
tableData = readtable(path, options);
end

function logicalValues = asLogical(values)
if islogical(values)
    logicalValues=values;
elseif isnumeric(values)
    logicalValues=values~=0;
else
    logicalValues=ismember(lower(string(values)),["true","1","yes"]);
end
end

function styleAxes(ax,gridColor)
ax.Box='off';
ax.TickDir='out';
ax.XColor=[0.16,0.16,0.16]; ax.YColor=[0.16,0.16,0.16];
ax.GridColor=gridColor; ax.GridAlpha=0.8; ax.MinorGridAlpha=0.35;
ax.XGrid='off'; ax.YGrid='on';
ax.Layer='top';
end

function exportFigure(fig,path)
set(fig,'Renderer','painters');
exportgraphics(fig,path,'Resolution',300,'BackgroundColor','white');
close(fig);
end

function ensureDir(path)
if ~exist(path,'dir')
    mkdir(path);
end
end
